content:
:root {
  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-text-main: #0f172a;
  --color-text-muted: #64748b;
  --color-border: #e2e8f0;
  --color-bg-page: #f8fafc;
  --color-bg-card: #ffffff;
  --color-row-hover: #f1f5f9;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Hiragino Sans", "Meiryo", sans-serif;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-page);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アプリ全体ラッパー */
.app-wrapper {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 20px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ヘッダーエリア */
.header-container {
  margin-bottom: 24px;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 10px;
}

.app-subtitle {
  font-size: 0.925rem;
  color: var(--color-text-muted);
  margin-top: 6px;
}

/* コントロールパネル (検索・件数表示) */
.control-panel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

/* 検索ボックス */
.search-box {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 260px;
  max-width: 420px;
}

.search-icon {
  position: absolute;
  left: 14px;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 10px 38px 10px 40px;
  font-size: 0.95rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-bg-card);
  color: var(--color-text-main);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.search-input::placeholder {
  color: #94a3b8;
}

.clear-button {
  position: absolute;
  right: 10px;
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  font-size: 1rem;
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  line-height: 1;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.clear-button:hover {
  background-color: #e2e8f0;
  color: var(--color-text-main);
}

/* 該当件数バッジ */
.info-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  background-color: var(--color-bg-card);
  padding: 6px 14px;
  border-radius: 9999px;
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  white-space: nowrap;
}

.info-badge strong {
  color: var(--color-primary);
  font-weight: 700;
}

/* テーブルカード */
.table-card {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border);
  overflow: hidden;
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/* テーブル本体 */
.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

/* テーブルヘッダー */
.employee-table thead {
  background-color: #f8fafc;
  border-bottom: 2px solid var(--color-border);
}

.table-th {
  padding: 14px 18px;
  font-weight: 600;
  color: #475569;
  letter-spacing: 0.02em;
  user-select: none;
  white-space: nowrap;
}

.table-th-sortable {
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.table-th-sortable:hover {
  background-color: #edf2f7;
  color: var(--color-primary);
}

.table-th-sortable:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: -2px;
  background-color: #edf2f7;
  color: var(--color-primary);
}

.table-th-sortable:active {
  background-color: #e2e8f0;
}

.sort-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: 6px;
  vertical-align: middle;
  font-size: 0.85rem;
  color: var(--color-primary);
  transition: transform 0.2s ease, opacity 0.15s ease;
}

/* テーブル行 */
.table-tr {
  border-bottom: 1px solid var(--color-border);
  transition: background-color 0.15s ease;
}

.table-tr:last-child {
  border-bottom: none;
}

.table-tr:hover {
  background-color: var(--color-row-hover);
}

.table-td {
  padding: 14px 18px;
  vertical-align: middle;
  color: var(--color-text-main);
  white-space: nowrap;
}

/* 部署バッジ */
.dept-badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 0.825rem;
  font-weight: 500;
  background-color: #f1f5f9;
  color: #334155;
  border: 1px solid #cbd5e1;
  white-space: nowrap;
}

/* 部署ごとのカラフルな表現 */
.dept-badge[data-dept="営業部"] {
  background-color: #eff6ff;
  color: #1d4ed8;
  border-color: #bfdbfe;
}

.dept-badge[data-dept="開発部"] {
  background-color: #f0fdf4;
  color: #15803d;
  border-color: #bbf7d0;
}

.dept-badge[data-dept="人事部"] {
  background-color: #fdf2f8;
  color: #be185d;
  border-color: #fbcfe8;
}

.dept-badge[data-dept="総務部"] {
  background-color: #fefce8;
  color: #a16207;
  border-color: #fef08a;
}

.dept-badge[data-dept="マーケティング部"] {
  background-color: #faf5ff;
  color: #7e22ce;
  border-color: #e9d5ff;
}

/* 年齢表示 */
.age-text {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  color: #334155;
}

/* 該当なし空ステート */
.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: var(--color-text-muted);
}

.empty-state p {
  font-size: 1rem;
  margin-bottom: 16px;
}

/* リセットボタン */
.reset-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background-color: var(--color-primary);
  color: #ffffff;
  border: none;
  padding: 8px 18px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
  box-shadow: var(--shadow-sm);
}

.reset-button:hover {
  background-color: var(--color-primary-hover);
  box-shadow: var(--shadow-md);
}

.reset-button:active {
  transform: translateY(1px);
}

/* レスポンシブ対応 (スマートフォン・タブレット) */
@media (max-width: 640px) {
  .app-wrapper {
    padding: 20px 12px;
  }

  .app-title {
    font-size: 1.4rem;
  }

  .control-panel {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .search-box {
    max-width: 100%;
    min-width: 0;
  }

  .info-badge {
    align-self: flex-start;
  }

  .table-th,
  .table-td {
    padding: 12px 14px;
    font-size: 0.875rem;
  }
}

export type Department = '営業部' | '開発部' | '人事部' | '総務部' | 'マーケティング部';

export interface Employee {
  id: number;
  name: string;
  department: Department;
  age: number;
}

export type SortKey = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc' | null;

export type SortConfig = {
  key: SortKey;
  order: 'asc' | 'desc';
} | null;

import { Employee } from './types';

export const INITIAL_EMPLOYEES: readonly Employee[] = [
  {
    id: 1,
    name: '佐藤 健太',
    department: '営業部',
    age: 28,
  },
  {
    id: 2,
    name: '田中 美咲',
    department: '開発部',
    age: 32,
  },
  {
    id: 3,
    name: '鈴木 一郎',
    department: '人事部',
    age: 45,
  },
  {
    id: 4,
    name: '高橋 雅彦',
    department: '開発部',
    age: 24,
  },
  {
    id: 5,
    name: '伊藤 恵子',
    department: '総務部',
    age: 39,
  },
  {
    id: 6,
    name: '渡辺 大輔',
    department: 'マーケティング部',
    age: 29,
  },
  {
    id: 7,
    name: '中村 結衣',
    department: '営業部',
    age: 35,
  },
  {
    id: 8,
    name: '小林 誠',
    department: '開発部',
    age: 41,
  },
  {
    id: 9,
    name: '加藤 翔平',
    department: 'マーケティング部',
    age: 26,
  },
  {
    id: 10,
    name: '吉田 真由美',
    department: '人事部',
    age: 52,
  },
] as const;

import { useState, useMemo, useRef } from 'react';
import { Search, X, ArrowUpDown, ArrowUp, ArrowDown, Users, RotateCcw } from 'lucide-react';
import { INITIAL_EMPLOYEES } from './data';
import { Employee, SortKey } from './types';
import './index.css';

interface SortConfig {
  key: SortKey;
  order: 'asc' | 'desc';
}

export default function App() {
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // ソートの切り替えハンドラ（未選択 -> 昇順 -> 降順 -> 未選択）
  const handleSort = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) {
      setSortConfig({ key, order: 'asc' });
    } else if (sortConfig.order === 'asc') {
      setSortConfig({ key, order: 'desc' });
    } else {
      setSortConfig(null);
    }
  };

  // キーボード操作によるソート実行
  const handleKeyDown = (e: React.KeyboardEvent, key: SortKey) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleSort(key);
    }
  };

  // 検索入力クリアとフォーカス復帰
  const handleClear = () => {
    setSearchQuery('');
    inputRef.current?.focus();
  };

  // 検索条件・ソートのリセット
  const handleReset = () => {
    setSearchQuery('');
    setSortConfig(null);
    inputRef.current?.focus();
  };

  // 絞り込みおよびソート処理
  const processedEmployees = useMemo(() => {
    const trimmedQuery = searchQuery.trim().toLowerCase();

    // 名前による絞り込み
    let result = INITIAL_EMPLOYEES.filter((emp: Employee) => {
      if (!trimmedQuery) return true;
      return emp.name.toLowerCase().includes(trimmedQuery);
    });

    // ソート処理
    if (sortConfig) {
      result = [...result].sort((a: Employee, b: Employee) => {
        let comparison = 0;
        if (sortConfig.key === 'age') {
          comparison = a.age - b.age;
        } else {
          comparison = a[sortConfig.key].localeCompare(b[sortConfig.key], 'ja');
        }
        return sortConfig.order === 'asc' ? comparison : -comparison;
      });
    }

    return result;
  }, [searchQuery, sortConfig]);

  // aria-sort 属性値の判定
  const getAriaSort = (key: SortKey): 'ascending' | 'descending' | 'none' => {
    if (!sortConfig || sortConfig.key !== key) return 'none';
    return sortConfig.order === 'asc' ? 'ascending' : 'descending';
  };

  // ソートアイコンの描画ヘルパー
  const renderSortIndicator = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) {
      return (
        <span className="sort-indicator" aria-hidden="true">
          <ArrowUpDown size={14} style={{ opacity: 0.4 }} />
        </span>
      );
    }

    return (
      <span className="sort-indicator" aria-hidden="true">
        {sortConfig.order === 'asc' ? <ArrowUp size={14} /> : <ArrowDown size={14} />}
      </span>
    );
  };

  return (
    <div className="app-wrapper">
      {/* ヘッダーエリア */}
      <header className="header-container">
        <h1 className="app-title">
          <Users size={28} />
          社員名簿一覧
        </h1>
        <p className="app-subtitle">
          社員情報の閲覧・名前によるリアルタイム絞り込み検索・各列の昇順/降順ソートが可能です。
        </p>
      </header>

      {/* コントロールパネル */}
      <div className="control-panel">
        <div className="search-box">
          <span className="search-icon" aria-hidden="true">
            <Search size={18} />
          </span>
          <input
            ref={inputRef}
            type="text"
            className="search-input"
            placeholder="社員名で検索..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            aria-label="社員名で検索"
          />
          {searchQuery && (
            <button
              type="button"
              className="clear-button"
              onClick={handleClear}
              aria-label="検索内容をクリア"
              title="クリア"
            >
              <X size={16} />
            </button>
          )}
        </div>

        <div className="info-badge">
          表示中: <strong>{processedEmployees.length}</strong> / {INITIAL_EMPLOYEES.length} 名
        </div>
      </div>

      {/* テーブルカード */}
      <div className="table-card">
        {processedEmployees.length > 0 ? (
          <div className="table-wrapper">
            <table className="employee-table">
              <thead>
                <tr>
                  <th className="table-th" style={{ width: '80px' }}>
                    ID
                  </th>
                  <th
                    className="table-th table-th-sortable"
                    role="button"
                    tabIndex={0}
                    onClick={() => handleSort('name')}
                    onKeyDown={(e) => handleKeyDown(e, 'name')}
                    aria-sort={getAriaSort('name')}
                    title="氏名で並べ替え"
                  >
                    氏名
                    {renderSortIndicator('name')}
                  </th>
                  <th
                    className="table-th table-th-sortable"
                    role="button"
                    tabIndex={0}
                    onClick={() => handleSort('department')}
                    onKeyDown={(e) => handleKeyDown(e, 'department')}
                    aria-sort={getAriaSort('department')}
                    title="部署で並べ替え"
                  >
                    部署
                    {renderSortIndicator('department')}
                  </th>
                  <th
                    className="table-th table-th-sortable"
                    role="button"
                    tabIndex={0}
                    onClick={() => handleSort('age')}
                    onKeyDown={(e) => handleKeyDown(e, 'age')}
                    aria-sort={getAriaSort('age')}
                    title="年齢で並べ替え"
                  >
                    年齢
                    {renderSortIndicator('age')}
                  </th>
                </tr>
              </thead>
              <tbody>
                {processedEmployees.map((employee: Employee) => (
                  <tr key={employee.id} className="table-tr">
                    <td className="table-td">#{employee.id}</td>
                    <td className="table-td" style={{ fontWeight: 600 }}>
                      {employee.name}
                    </td>
                    <td className="table-td">
                      <span className="dept-badge" data-dept={employee.department}>
                        {employee.department}
                      </span>
                    </td>
                    <td className="table-td">
                      <span className="age-text">{employee.age}</span> 歳
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="empty-state">
            <p>「{searchQuery}」に一致する社員は見つかりませんでした。</p>
            <button type="button" className="reset-button" onClick={handleReset}>
              <RotateCcw size={16} />
              検索条件をリセット
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
